PAGE_ID='living-water-candidate-01'

def page():
    return {'id':PAGE_ID,'name':'Living Water · Candidate 01','canvas':{'w':1440,'h':960},'nodes':[],
      'design_experiment':{'schema':'dore.design-experiment.v1','track':'living-water-homepage','candidate':'01','status':'design-candidate','source_issue':531,
      'principles':['whole-page-flow','scripture-cinema','8:5-worlds','temporal-hierarchy','viewport-conductor','depth','confluence','enter-settle-return']}}

def install_workspace(base):
    original=base.workspace
    def workspace():
        w=original()
        if not any(p.get('id')==PAGE_ID for p in w.get('pages',[])):
            w['pages'].append(page());w=base.save(w)
        return w
    base.workspace=workspace

